<section><div class="page-head"><div><p class="eyebrow">Lightweight CRM</p><h1>Customers</h1><p class="muted">Customers are merged per store using their normalized international phone number.</p></div></div>
<form class="customer-search" method="get" action="/merchant/customers"><label class="sr-only" for="customer-search">Search customers</label><input id="customer-search" name="q" value="<?= e($query) ?>" placeholder="Customer name or phone"><button class="button secondary" type="submit">Search</button></form>
<?php if(!$customers['items']):?><div class="panel empty-state"><div class="empty-icon">○</div><h2><?= $query!==''?'No matching customers':'Customers will appear after they place orders.' ?></h2><p><?= $query!==''?'Try another name or international phone number.':'No separate customer account is required.' ?></p><?php if($query!==''):?><a class="button secondary" href="/merchant/customers">Clear search</a><?php endif ?></div><?php else:?><div class="customer-grid"><?php foreach($customers['items']as$customer):?><a class="panel customer-card" href="/merchant/customers/<?= e($customer['id']) ?>"><span class="customer-avatar" aria-hidden="true"><?= e(mb_strtoupper(mb_substr($customer['name'],0,1))) ?></span><div><h2><?= e($customer['name']) ?></h2><p><?= e($customer['phone']) ?></p><small>Last order <?= e(gmdate('M j, Y',strtotime($customer['last_order_at']))) ?></small></div><dl><div><dt>Orders</dt><dd><?= e($customer['order_count']) ?></dd></div><div><dt>Value</dt><dd><?= e($customer['currency_code']?:$store['currency_code']) ?> <?= e($customer['total_value']) ?></dd></div></dl></a><?php endforeach ?></div><?php endif ?>
<?php if($customers['pages']>1):?><nav class="pagination" aria-label="Customer pages"><?php $base='/merchant/customers?'.http_build_query(['q'=>$query]);if($customers['page']>1):?><a class="button secondary compact" href="<?= e($base.'&page='.($customers['page']-1)) ?>">Previous</a><?php endif ?><span>Page <?= e($customers['page']) ?> of <?= e($customers['pages']) ?></span><?php if($customers['page']<$customers['pages']):?><a class="button secondary compact" href="<?= e($base.'&page='.($customers['page']+1)) ?>">Next</a><?php endif ?></nav><?php endif ?></section>
